<?php
/** Native WooPayments button is generated by woocommerce_after_add_to_cart_form. */
defined( 'ABSPATH' ) || exit;
if ( ! function_exists( 'dtb_staging_native_wallet_allowed' ) || ! dtb_staging_native_wallet_allowed() ) {
    status_header( 404 );
    exit;
}
$product_id = dtb_staging_native_wallet_request_id();
nocache_headers();
?><!doctype html>
<html <?php language_attributes(); ?>>
<head>
<meta charset="<?php bloginfo( 'charset' ); ?>">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<title>WooPayments staging wallet preview</title>
<style>
html,body{margin:0;padding:0;overflow:hidden;background:transparent}
body{font:14px/1.3 system-ui,sans-serif}
.woocommerce-product-gallery,.product_title,.price,.woocommerce-product-details__short-description,
.product_meta,.woocommerce-tabs,.related,.upsells,.woocommerce-breadcrumb,
.woocommerce-notices-wrapper,.woocommerce-message,.woocommerce-info{display:none!important}
.woocommerce div.product .summary{float:none!important;width:100%!important;margin:0!important}
.woocommerce div.product form.cart{margin:0!important}
.woocommerce div.product form.cart :is(.quantity,.single_add_to_cart_button,.variations,.single_variation_wrap){position:absolute!important;left:-200vw!important}
.woocommerce div.product .wcpay-express-checkout-wrapper{margin:0!important;padding:0!important;width:100%!important}
#wcpay-express-checkout-element{width:100%;min-height:48px}
</style>
<?php wp_head(); ?>
</head>
<body <?php body_class( 'dtb-native-wallet-iframe' ); ?>>
<div class="woocommerce">
<?php
// Preserve all native WooCommerce and WooPayments product hooks/JS.
while ( have_posts() ) {
    the_post();
    wc_get_template_part( 'content', 'single-product' );
}
?>
</div>
<script>
(function(){
  'use strict';
  var id = <?php echo wp_json_encode( $product_id ); ?>;
  var mount = document.getElementById('wcpay-express-checkout-element');
  function setQuantity(quantity) {
    var field = document.querySelector('form.cart input.qty');
    if (!field) return;
    var value = Number(quantity);
    if (!Number.isInteger(value) || value < 1 || value > 99) return;
    field.value = String(value);
    field.dispatchEvent(new Event('change', { bubbles: true }));
  }
  window.addEventListener('message', function(event) {
    if (event.origin !== window.location.origin || event.source !== window.parent) return;
    if (event.data && event.data.type === 'dtb-native-wallet-quantity' && event.data.productId === id) {
      setQuantity(event.data.quantity);
    }
  });
  var announced = false;
  function notify(){
    if (announced) return;
    mount = mount || document.getElementById('wcpay-express-checkout-element');
    // The Stripe-owned child is the initialization signal. No fake buttons.
    if (mount && (mount.childElementCount || mount.shadowRoot && mount.shadowRoot.childElementCount)) {
      announced = true;
      window.parent.postMessage({type:'dtb-native-wallet-mounted',productId:id},window.location.origin);
    }
  }
  var observer = new MutationObserver(notify);
  observer.observe(document.documentElement,{subtree:true,childList:true});
  window.addEventListener('load', notify);
  setTimeout(function(){observer.disconnect();if(!announced)window.parent.postMessage({type:'dtb-native-wallet-unavailable',productId:id},window.location.origin)},12000);
}());
</script>
<?php wp_footer(); ?>
</body>
</html>
